-- ==== 20260924003900_ai_cost_alerts.sql
-- AI API cost per user, and alerts when it runs high.
--
-- Every AI call's token usage is already recorded per upload (syllabus_uploads.ai_usage:
-- [{ step, model, inputTokens, outputTokens, cacheReadTokens }]). Costs are computed from
-- ai_model_prices, a table (not code) so prices can be updated without a deploy. A model
-- with no price row is costed at the highest known rate, so a new or misspelled model
-- can only make alerts fire earlier, never hide spend.
--
-- The ai-cost-monitor function (hourly) records an alert, at most once per day each, when
-- a user's AI cost over the last 24 hours passes a threshold, or when total spend does.

create table public.ai_model_prices (
  model text primary key,
  -- US cents per million tokens.
  input_cents_per_mtok numeric(10, 4) not null check (input_cents_per_mtok >= 0),
  output_cents_per_mtok numeric(10, 4) not null check (output_cents_per_mtok >= 0),
  cache_read_cents_per_mtok numeric(10, 4) not null check (cache_read_cents_per_mtok >= 0),
  updated_at timestamptz not null default now()
);
alter table public.ai_model_prices enable row level security;
revoke all on public.ai_model_prices from anon, authenticated;

-- Anthropic first-party API list prices (as of 2026-06). Cache reads use the published
-- rate where there is one, else 0.1x input.
insert into public.ai_model_prices (model, input_cents_per_mtok, output_cents_per_mtok, cache_read_cents_per_mtok) values
  ('claude-fable-5-1', 1000, 5000, 25),
  ('claude-fable-5',   1000, 5000, 100),
  ('claude-opus-5-5',  400,  2000, 20),
  ('claude-opus-5',    500,  2500, 50),
  ('claude-opus-4-8',  500,  2500, 50),
  ('claude-opus-4-7',  500,  2500, 50),
  ('claude-opus-4-6',  500,  2500, 50),
  ('claude-sonnet-5',  200,  1000, 20),
  ('claude-sonnet-4-6', 300, 1500, 30),
  ('claude-haiku-4-5', 100,  500,  10);

create table public.ai_cost_alerts (
  id bigint generated always as identity primary key,
  -- null: the total across all users.
  user_id uuid references public.profiles (id) on delete cascade,
  alert_date date not null,
  cost_cents numeric(12, 4) not null,
  threshold_cents numeric(12, 4) not null,
  uploads integer not null,
  created_at timestamptz not null default now()
);
create unique index ai_cost_alerts_user_day on public.ai_cost_alerts (user_id, alert_date) where user_id is not null;
create unique index ai_cost_alerts_total_day on public.ai_cost_alerts (alert_date) where user_id is null;
alter table public.ai_cost_alerts enable row level security;
revoke all on public.ai_cost_alerts from anon, authenticated;

-- Cost in cents of one upload's recorded AI calls.
create or replace function private.ai_usage_cost_cents(p_usage jsonb)
returns numeric
language sql
stable
set search_path = ''
as $$
  with fallback as (
    select max(input_cents_per_mtok) as i, max(output_cents_per_mtok) as o, max(cache_read_cents_per_mtok) as c
    from public.ai_model_prices
  )
  select coalesce(sum(
      coalesce((u ->> 'inputTokens')::numeric, 0) * coalesce(p.input_cents_per_mtok, f.i)
    + coalesce((u ->> 'outputTokens')::numeric, 0) * coalesce(p.output_cents_per_mtok, f.o)
    + coalesce((u ->> 'cacheReadTokens')::numeric, 0) * coalesce(p.cache_read_cents_per_mtok, f.c)
  ) / 1000000, 0)
  from jsonb_array_elements(case when jsonb_typeof(p_usage) = 'array' then p_usage else '[]' end) u
  cross join fallback f
  left join public.ai_model_prices p on p.model = u ->> 'model';
$$;
revoke execute on function private.ai_usage_cost_cents(jsonb) from public, anon, authenticated;

-- AI cost per user between p_since and p_until (inclusive), highest first. Service role only.
create or replace function public.ai_cost_by_user(p_since timestamptz, p_until timestamptz default now())
returns table (user_id uuid, uploads integer, cost_cents numeric)
language sql
stable
security definer
set search_path = ''
as $$
  select s.user_id, count(*)::integer, round(sum(private.ai_usage_cost_cents(s.ai_usage)), 4)
  from public.syllabus_uploads s
  where s.created_at >= p_since and s.created_at <= p_until and s.ai_usage <> '[]'::jsonb
  group by s.user_id
  order by 3 desc;
$$;

-- Records new alerts for the last 24 hours (at most one per user per day, and one for
-- the total) and returns only the ones created by this call. Service role only.
create or replace function public.record_ai_cost_alerts(p_user_threshold_cents numeric, p_total_threshold_cents numeric)
returns table (user_id uuid, cost_cents numeric, threshold_cents numeric, uploads integer)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_today date := (now() at time zone 'UTC')::date;
begin
  return query
  with per_user as (
    select * from public.ai_cost_by_user(now() - interval '24 hours')
  ),
  user_alerts as (
    insert into public.ai_cost_alerts (user_id, alert_date, cost_cents, threshold_cents, uploads)
    select pu.user_id, v_today, pu.cost_cents, p_user_threshold_cents, pu.uploads
    from per_user pu
    where pu.cost_cents >= p_user_threshold_cents
    on conflict (user_id, alert_date) where user_id is not null do nothing
    returning ai_cost_alerts.user_id, ai_cost_alerts.cost_cents, ai_cost_alerts.threshold_cents, ai_cost_alerts.uploads
  ),
  total_alert as (
    insert into public.ai_cost_alerts (user_id, alert_date, cost_cents, threshold_cents, uploads)
    select null, v_today, sum(pu.cost_cents), p_total_threshold_cents, sum(pu.uploads)::integer
    from per_user pu
    having coalesce(sum(pu.cost_cents), 0) >= p_total_threshold_cents
    on conflict (alert_date) where user_id is null do nothing
    returning ai_cost_alerts.user_id, ai_cost_alerts.cost_cents, ai_cost_alerts.threshold_cents, ai_cost_alerts.uploads
  )
  select * from user_alerts
  union all
  select * from total_alert;
end;
$$;

revoke execute on function public.ai_cost_by_user(timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function public.record_ai_cost_alerts(numeric, numeric) from public, anon, authenticated;
grant execute on function public.ai_cost_by_user(timestamptz, timestamptz) to service_role;
grant execute on function public.record_ai_cost_alerts(numeric, numeric) to service_role;

select cron.schedule('ai-cost-monitor', '7 * * * *', $$ select private.invoke_edge_function('ai-cost-monitor') $$);

-- ==== 20260924004000_today_overview.sql
-- Everything the Today screen shows besides the ranked feed, in one call, computed in
-- the user's timezone: the three metric cards, today's review blocks, the next exam,
-- and the user's courses (code and color for chips). Runs as the caller, so RLS applies.

create or replace function public.get_today_overview()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_tz text;
  v_now timestamptz := now();
  v_today date;
  v_week_start date;
  v_week_end date;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select timezone into v_tz from public.profiles where id = v_user;
  v_today := (v_now at time zone v_tz)::date;
  -- Weeks run Monday to Sunday.
  v_week_start := date_trunc('week', v_today::timestamp)::date;
  v_week_end := v_week_start + 6;

  return jsonb_build_object(
    'timezone', v_tz,
    'today', v_today,
    'week_start', v_week_start,

    -- Open work due from now through Sunday.
    'due_this_week', (
      select count(*)
      from public.assignments a
      join public.courses c on c.id = a.course_id and c.archived_at is null
      where a.status in ('todo', 'in_progress')
        and a.due_at >= v_now
        and (a.due_at at time zone v_tz)::date <= v_week_end
    ),

    -- Minutes from finished sessions that started this week.
    'focus_minutes_this_week', (
      select coalesce(sum(s.duration_minutes), 0)
      from public.study_sessions s
      where s.user_id = v_user and s.duration_minutes is not null
        and (s.started_at at time zone v_tz)::date between v_week_start and v_week_end
    ),

    -- Courses whose current grade is below the student's target.
    'courses_at_risk', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'code', r.code, 'current', r.current, 'target', r.target) order by r.code)
      from (
        select c.id, coalesce(c.code, c.name) as code, public.course_current_grade(c.id) as current, c.target_grade as target
        from public.courses c
        where c.archived_at is null and c.target_grade is not null
      ) r
      where r.current is not null and r.current < r.target
    ), '[]'::jsonb),

    -- Review and exam-prep blocks scheduled today, in time order.
    'reviews', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', b.id, 'kind', b.kind, 'status', b.status,
        'starts_at', b.starts_at, 'ends_at', b.ends_at, 'minutes', b.duration_minutes,
        'course_id', b.course_id, 'assignment_id', b.assignment_id,
        'title', coalesce(a.title, c.name)
      ) order by b.starts_at)
      from public.study_blocks b
      join public.courses c on c.id = b.course_id and c.archived_at is null
      left join public.assignments a on a.id = b.assignment_id
      where b.kind in ('review', 'exam_prep')
        and (b.starts_at at time zone v_tz)::date = v_today
    ), '[]'::jsonb),

    'next_exam', (
      select jsonb_build_object(
        'id', a.id, 'title', a.title, 'course_id', a.course_id, 'due_at', a.due_at,
        'days_until', (a.due_at at time zone v_tz)::date - v_today
      )
      from public.assignments a
      join public.courses c on c.id = a.course_id and c.archived_at is null
      where a.kind = 'exam' and a.status in ('todo', 'in_progress') and a.due_at >= v_now
      order by a.due_at
      limit 1
    ),

    'courses', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'code', coalesce(c.code, c.name), 'name', c.name, 'color', c.color) order by c.name)
      from public.courses c
      where c.archived_at is null
    ), '[]'::jsonb)
  );
end;
$$;

revoke execute on function public.get_today_overview() from public, anon;
grant execute on function public.get_today_overview() to authenticated;

-- ==== 20260924004100_course_meetings.sql
-- Study system, part 1 (prompt 71): weekly class meetings, parsed from syllabi, and a
-- "make 5-20 cards" task after each class, due within 24 hours of it ending.

create table public.course_meetings (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  -- ISO weekday: 1 = Monday ... 7 = Sunday.
  weekday smallint not null check (weekday between 1 and 7),
  -- Local wall-clock times in the user's timezone (profiles.timezone).
  start_time time not null,
  end_time time not null,
  kind text not null default 'lecture' check (kind in ('lecture', 'lab', 'discussion', 'other')),
  location text check (char_length(location) <= 200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint course_meetings_positive_duration check (end_time > start_time),
  constraint course_meetings_unique unique (course_id, weekday, start_time, kind),
  -- Target for the composite foreign key from assignments.
  constraint course_meetings_id_course_key unique (id, course_id)
);

create index course_meetings_course_idx on public.course_meetings (course_id);

create trigger course_meetings_updated_at before update on public.course_meetings
for each row execute function public.set_updated_at();

alter table public.course_meetings enable row level security;

create policy "Users can view meetings of their courses"
on public.course_meetings for select to authenticated
using ((select private.owns_course(course_id)));

create policy "Users can create meetings in their courses"
on public.course_meetings for insert to authenticated
with check ((select private.owns_course(course_id)));

create policy "Users can update meetings of their courses"
on public.course_meetings for update to authenticated
using ((select private.owns_course(course_id)))
with check ((select private.owns_course(course_id)));

create policy "Users can delete meetings of their courses"
on public.course_meetings for delete to authenticated
using ((select private.owns_course(course_id)));

revoke all on public.course_meetings from anon;

-- Card tasks are ordinary assignments (so they rank in Today, show on the calendar, and
-- get reminders) that remember which class they follow. The composite key keeps the
-- meeting inside the assignment's own course; one task per meeting per class date.
alter table public.assignments
  add column meeting_id uuid,
  add column class_date date,
  add constraint assignments_meeting_fkey foreign key (meeting_id, course_id)
    references public.course_meetings (id, course_id) on delete set null (meeting_id),
  add constraint assignments_class_date_needs_meeting check (class_date is null or meeting_id is not null);

create unique index assignments_meeting_class_key on public.assignments (meeting_id, class_date)
  where meeting_id is not null;

alter table public.assignments drop constraint assignments_source_check;
alter table public.assignments add constraint assignments_source_check
  check (source in ('manual', 'syllabus', 'canvas', 'study_system'));

-- Students can turn card tasks off.
alter table public.profiles add column card_tasks_enabled boolean not null default true;

-- Creates the card task for every class that ended in the last 24 hours (in each user's
-- timezone) and doesn't have one yet. Idempotent, so it can run as often as we like and
-- catches up after a missed run. Skips archived courses, days outside the term, and
-- classes that ended before the meeting was added.
create or replace function private.create_card_tasks()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  with classes as (
    select m.id as meeting_id, m.course_id, coalesce(c.code, c.name) as course_label, d.class_date,
           (d.class_date + m.end_time) at time zone p.timezone as ended_at
    from public.course_meetings m
    join public.courses c on c.id = m.course_id and c.archived_at is null
    join public.profiles p on p.id = c.user_id and p.card_tasks_enabled
    cross join lateral (
      -- Yesterday and today in the user's timezone cover every class that ended in the last day.
      select ((now() at time zone p.timezone)::date - g) as class_date from generate_series(0, 1) g
    ) d
    where extract(isodow from d.class_date) = m.weekday
      and (c.term_start is null or d.class_date >= c.term_start)
      and (c.term_end is null or d.class_date <= c.term_end)
  )
  insert into public.assignments (course_id, title, kind, due_at, estimated_minutes, source, meeting_id, class_date)
  select k.course_id,
         format('Make 5–20 cards: %s, %s class', k.course_label, to_char(k.class_date, 'Dy Mon FMDD')),
         'other', k.ended_at + interval '24 hours', 20, 'study_system', k.meeting_id, k.class_date
  from classes k
  join public.course_meetings m on m.id = k.meeting_id
  where k.ended_at <= now()
    and k.ended_at > now() - interval '24 hours'
    and k.ended_at >= m.created_at
  on conflict (meeting_id, class_date) where meeting_id is not null do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke execute on function private.create_card_tasks() from public, anon, authenticated;

select cron.schedule('create-card-tasks', '*/15 * * * *', $$ select private.create_card_tasks() $$);

-- commit_parsed_syllabus also stores the class meetings (payload.meetings, optional).
create or replace function public.commit_parsed_syllabus(p_upload_id uuid, p_payload jsonb default null)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_upload record;
  v_payload jsonb;
  v_course jsonb;
  v_course_id uuid;
  v_categories jsonb;
  v_assignments jsonb;
  v_meetings jsonb;
  v_bad text;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select * into v_upload from private.claim_upload_for_commit(p_upload_id);
  if not found then
    raise exception 'syllabus upload % not found', p_upload_id using errcode = 'P0002';
  end if;
  if v_upload.status = 'committed' and v_upload.course_id is not null then
    return v_upload.course_id; -- retry of a successful commit
  end if;
  if v_upload.status <> 'parsed' then
    raise exception 'syllabus upload is %, not parsed', v_upload.status using errcode = '55000';
  end if;

  v_payload := coalesce(p_payload, v_upload.parse_result);
  v_course := v_payload -> 'course';
  v_categories := coalesce(v_payload -> 'categories', '[]'::jsonb);
  v_assignments := coalesce(v_payload -> 'assignments', '[]'::jsonb);
  v_meetings := coalesce(v_payload -> 'meetings', '[]'::jsonb);

  -- Shape checks with clear messages; column constraints catch the rest.
  if jsonb_typeof(v_course) is distinct from 'object' then
    raise exception 'payload.course must be an object' using errcode = '22023';
  end if;
  if jsonb_typeof(v_categories) <> 'array' or jsonb_typeof(v_assignments) <> 'array' then
    raise exception 'payload.categories and payload.assignments must be arrays' using errcode = '22023';
  end if;
  if jsonb_typeof(v_meetings) <> 'array' then
    raise exception 'payload.meetings must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(v_categories) > 30 or jsonb_array_length(v_assignments) > 500
     or jsonb_array_length(v_meetings) > 30 then
    raise exception 'too many categories or assignments' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_categories) c
    where jsonb_typeof(c) <> 'object' or nullif(trim(c ->> 'name'), '') is null
  ) then
    raise exception 'every category needs a name' using errcode = '22023';
  end if;
  if exists (
    select lower(trim(c ->> 'name')) from jsonb_array_elements(v_categories) c
    group by 1 having count(*) > 1
  ) then
    raise exception 'category names must be unique' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_assignments) a
    where jsonb_typeof(a) <> 'object' or nullif(trim(a ->> 'title'), '') is null
  ) then
    raise exception 'every assignment needs a title' using errcode = '22023';
  end if;
  select a ->> 'category_name' into v_bad
  from jsonb_array_elements(v_assignments) a
  where nullif(trim(a ->> 'category_name'), '') is not null
    and not exists (
      select 1 from jsonb_array_elements(v_categories) c
      where lower(trim(c ->> 'name')) = lower(trim(a ->> 'category_name'))
    )
  limit 1;
  if v_bad is not null then
    raise exception 'assignment category "%" is not in categories', v_bad using errcode = '22023';
  end if;

  -- Course
  insert into public.courses (user_id, name, code, instructor, term_start, term_end, target_grade, color, letter_scale)
  values (
    v_user_id,
    trim(v_course ->> 'name'),
    nullif(trim(v_course ->> 'code'), ''),
    nullif(trim(v_course ->> 'instructor'), ''),
    (v_course ->> 'term_start')::date,
    (v_course ->> 'term_end')::date,
    (v_course ->> 'target_grade')::numeric,
    nullif(v_course ->> 'color', ''),
    nullif(v_course -> 'letter_scale', 'null'::jsonb)
  )
  returning id into v_course_id;

  -- Categories (weight null means "unknown"; store 0 so the student fills it in)
  insert into public.grade_categories (course_id, name, weight, drop_lowest, position)
  select
    v_course_id,
    trim(c.value ->> 'name'),
    coalesce((c.value ->> 'weight')::numeric, 0),
    coalesce((c.value ->> 'drop_lowest')::smallint, 0),
    (c.ordinality - 1)::smallint
  from jsonb_array_elements(v_categories) with ordinality as c;

  -- Assignments, linked to categories by case-insensitive name
  insert into public.assignments (
    course_id, category_id, title, kind, due_at, points_possible, estimated_minutes, source
  )
  select
    v_course_id,
    gc.id,
    trim(a ->> 'title'),
    coalesce(nullif(a ->> 'kind', ''), 'assignment')::public.assignment_kind,
    (a ->> 'due_at')::timestamptz,
    (a ->> 'points_possible')::numeric,
    (a ->> 'estimated_minutes')::integer,
    'syllabus'
  from jsonb_array_elements(v_assignments) a
  left join public.grade_categories gc
    on gc.course_id = v_course_id
   and lower(gc.name) = lower(trim(a ->> 'category_name'));

  -- Class meetings (weekday as mon..sun or ISO 1..7); duplicates collapse.
  insert into public.course_meetings (course_id, weekday, start_time, end_time, kind, location)
  select distinct on (w.weekday, (m ->> 'start_time')::time, coalesce(m ->> 'kind', 'lecture'))
    v_course_id,
    w.weekday,
    (m ->> 'start_time')::time,
    (m ->> 'end_time')::time,
    coalesce(nullif(m ->> 'kind', ''), 'lecture'),
    nullif(trim(m ->> 'location'), '')
  from jsonb_array_elements(v_meetings) m
  cross join lateral (
    select coalesce(
      array_position(array['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'], lower(m ->> 'weekday')),
      case when (m ->> 'weekday') ~ '^[1-7]$' then (m ->> 'weekday')::int end
    )::smallint as weekday
  ) w;

  perform private.mark_upload_committed(p_upload_id, v_course_id);
  return v_course_id;
end;
$$;

-- ==== 20260924004200_card_generations.sql
-- Study system, part 2 (prompt 72): notes -> retrieval cards. Each generation is logged
-- (for the daily limit and AI cost monitoring); the cards themselves go into flashcards,
-- so the Anki and Quizlet exports include them.

create table public.card_generations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  course_id uuid not null references public.courses (id) on delete cascade,
  assignment_id uuid references public.assignments (id) on delete set null,
  status text not null default 'pending' check (status in ('pending', 'done', 'failed')),
  notes_chars integer not null check (notes_chars > 0),
  card_count integer not null default 0 check (card_count >= 0),
  prompt_version text,
  error text,
  ai_usage jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index card_generations_user_created_idx on public.card_generations (user_id, created_at);

create trigger card_generations_set_updated_at before update on public.card_generations
for each row execute function public.set_updated_at();

-- Users can see their own history; only the edge function (service role) writes.
alter table public.card_generations enable row level security;

create policy "Users can view their card generations"
on public.card_generations for select to authenticated
using ((select auth.uid()) = user_id);

revoke all on public.card_generations from anon;
revoke insert, update, delete on public.card_generations from authenticated;

-- Limits: Free 5 generations a day, Pro 50 (the user's local day). Failures before any AI
-- call don't count; failures after one do, so forcing errors can't buy free AI work.
create or replace function private.card_generation_limit(p_user_id uuid)
returns integer
language sql
stable
set search_path = ''
as $$
  select case when public.is_pro(p_user_id) then 50 else 5 end;
$$;

create or replace function private.card_generations_today(p_user_id uuid, p_timezone text)
returns integer
language sql
stable
set search_path = ''
as $$
  select count(*)::integer
  from public.card_generations g
  where g.user_id = p_user_id
    and g.created_at >= (date_trunc('day', now() at time zone p_timezone) at time zone p_timezone)
    and (g.status <> 'failed' or jsonb_array_length(g.ai_usage) > 0);
$$;

create or replace function private.enforce_card_generation_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_timezone text;
  v_limit integer;
begin
  -- Lock the profile row so concurrent requests can't both squeeze under the limit.
  select p.timezone into v_timezone from public.profiles p where p.id = new.user_id for update;
  v_limit := private.card_generation_limit(new.user_id);
  if private.card_generations_today(new.user_id, coalesce(v_timezone, 'UTC')) >= v_limit then
    raise exception 'Daily card limit reached (% per day)', v_limit
      using errcode = 'SPK01', hint = 'card_limit_reached';
  end if;
  return new;
end;
$$;

revoke execute on function private.enforce_card_generation_limit() from public, anon, authenticated;

create trigger card_generations_enforce_limit
before insert on public.card_generations
for each row execute function private.enforce_card_generation_limit();

-- Remaining generations today, for the notes screen.
create or replace function public.get_card_quota()
returns table (daily_limit integer, used_today integer, remaining integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_limit integer;
  v_used integer;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_limit := private.card_generation_limit(v_user);
  v_used := private.card_generations_today(
    v_user, coalesce((select timezone from public.profiles where id = v_user), 'UTC'));
  return query select v_limit, v_used, greatest(v_limit - v_used, 0);
end;
$$;

revoke execute on function public.get_card_quota() from public, anon;
grant execute on function public.get_card_quota() to authenticated;

-- AI cost monitoring (prompt 69) now counts card generations too. `uploads` still
-- counts syllabus uploads; `cost_cents` covers both.
create or replace function public.ai_cost_by_user(p_since timestamptz, p_until timestamptz default now())
returns table (user_id uuid, uploads integer, cost_cents numeric)
language sql
stable
security definer
set search_path = ''
as $$
  select x.user_id, sum(x.uploads)::integer, round(sum(x.cost), 4)
  from (
    select s.user_id, 1 as uploads, private.ai_usage_cost_cents(s.ai_usage) as cost
    from public.syllabus_uploads s
    where s.created_at >= p_since and s.created_at <= p_until and s.ai_usage <> '[]'::jsonb
    union all
    select g.user_id, 0, private.ai_usage_cost_cents(g.ai_usage)
    from public.card_generations g
    where g.created_at >= p_since and g.created_at <= p_until and g.ai_usage <> '[]'::jsonb
  ) x
  group by x.user_id
  order by 3 desc;
$$;

-- ==== 20260924004300_practice_quiz_kind.sql
-- Study system, part 3 (prompt 73): a study block kind for closed-note practice quizzes.
-- Its own migration because a new enum value can't be used in the transaction that adds it.
alter type public.study_block_kind add value if not exists 'practice_quiz';

-- ==== 20260924004310_today_reviews_first.sql
-- Study system, part 3 (prompt 73): review items before new work, and weekly
-- closed-note practice quizzes per course (twice weekly in the 2 weeks before an exam),
-- planned by packages/core/src/review/practice.ts.

alter table public.study_blocks drop constraint study_blocks_source_check;
alter table public.study_blocks add constraint study_blocks_source_check
  check (source in ('scheduler', 'review_plan', 'practice_plan', 'manual'));

-- Swaps the user's future, unlocked, still-planned practice quizzes for a fresh set.
-- A quiz the user moved (locked) or finished for the same course and local day is kept
-- instead of duplicated.
create or replace function public.replace_practice_plan(p_user_id uuid, p_from timestamptz, p_blocks jsonb)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_inserted integer;
  v_tz text;
begin
  if coalesce(auth.role(), '') <> 'service_role' and p_user_id is distinct from (select auth.uid()) then
    raise exception 'cannot replace another user''s practice plan' using errcode = '42501';
  end if;
  if jsonb_typeof(p_blocks) <> 'array' or jsonb_array_length(p_blocks) > 300 then
    raise exception 'p_blocks must be an array of at most 300 blocks' using errcode = '22023';
  end if;

  select coalesce((select timezone from public.profiles where id = p_user_id), 'UTC') into v_tz;

  delete from public.study_blocks
  where user_id = p_user_id
    and source = 'practice_plan'
    and status = 'planned'
    and not locked
    and starts_at >= p_from;

  insert into public.study_blocks (user_id, course_id, starts_at, ends_at, kind, source)
  select p_user_id, (b ->> 'course_id')::uuid, (b ->> 'starts_at')::timestamptz,
         (b ->> 'ends_at')::timestamptz, 'practice_quiz', 'practice_plan'
  from jsonb_array_elements(p_blocks) b
  where (b ->> 'starts_at')::timestamptz >= p_from
    and not exists (
      select 1 from public.study_blocks kept
      where kept.user_id = p_user_id
        and kept.source = 'practice_plan'
        and kept.course_id = (b ->> 'course_id')::uuid
        and (kept.starts_at at time zone v_tz)::date = ((b ->> 'starts_at')::timestamptz at time zone v_tz)::date
    );

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$$;

revoke execute on function public.replace_practice_plan(uuid, timestamptz, jsonb) from public, anon;
grant execute on function public.replace_practice_plan(uuid, timestamptz, jsonb) to authenticated, service_role;

-- The Today feed now starts with the day's review items (exam reviews, exam prep, and
-- practice quizzes), then the ranked tasks. Planned review time counts against the
-- day's capacity before any new work is ranked. New columns: item_type ('review' or
-- 'task'), item_id (the block or the assignment), block_kind, block_status, starts_at,
-- ends_at. assignment_id is null for practice quizzes; kind and status are null for
-- review items.
drop function public.get_today_feed(date);

create function public.get_today_feed(p_date date default null)
returns table (
  item_type text,
  item_id uuid,
  assignment_id uuid,
  course_id uuid,
  course_name text,
  title text,
  kind public.assignment_kind,
  status public.assignment_status,
  block_kind public.study_block_kind,
  block_status public.study_block_status,
  starts_at timestamptz,
  ends_at timestamptz,
  due_at timestamptz,
  grade_share numeric,
  minutes_remaining integer,
  planned_minutes integer,
  priority numeric,
  overdue boolean,
  rank integer,
  -- Capacity for the day (same on every row) so one call renders the header too.
  capacity_minutes integer,
  studied_minutes integer
)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_tz text;
  v_date date;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_now timestamptz := now();
  v_capacity integer;
  v_daily integer;
  v_studied integer;
  v_left integer;
  r record;
  v_rank integer := 0;
  v_planned integer;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select p.timezone, p.daily_study_minutes into v_tz, v_daily from public.profiles p where p.id = v_user_id;
  v_date := coalesce(p_date, (v_now at time zone v_tz)::date);
  v_day_start := v_date::timestamp at time zone v_tz;
  v_day_end := (v_date + 1)::timestamp at time zone v_tz;
  v_capacity := coalesce(public.study_capacity(v_user_id, v_date), 120);

  -- Time already studied today counts against the day's capacity.
  select coalesce(sum(extract(epoch from (least(coalesce(s.ended_at, v_now), v_day_end) - greatest(s.started_at, v_day_start))) / 60), 0)::integer
  into v_studied
  from public.study_sessions s
  where s.user_id = v_user_id
    and s.started_at < v_day_end
    and coalesce(s.ended_at, v_now) > v_day_start;

  v_left := greatest(v_capacity - v_studied, 0);

  -- 1. Review items first: the day's review, exam-prep, and practice-quiz blocks (done
  --    ones stay listed so they can be unchecked; missed ones drop off).
  for r in
    select b.id, b.assignment_id, b.course_id, c.name as course_name, b.kind, b.status,
           b.starts_at, b.ends_at, b.duration_minutes, a.title as assignment_title, a.due_at
    from public.study_blocks b
    join public.courses c on c.id = b.course_id and c.archived_at is null
    left join public.assignments a on a.id = b.assignment_id
    where b.user_id = v_user_id
      and b.kind in ('review', 'exam_prep', 'practice_quiz')
      and b.status in ('planned', 'done')
      and b.starts_at >= v_day_start and b.starts_at < v_day_end
    order by b.starts_at, b.id
  loop
    v_rank := v_rank + 1;
    if r.status = 'planned' then
      v_left := greatest(v_left - r.duration_minutes, 0);
    end if;
    item_type := 'review';
    item_id := r.id;
    assignment_id := r.assignment_id;
    course_id := r.course_id;
    course_name := r.course_name;
    title := case r.kind
      when 'practice_quiz' then 'Closed-note practice quiz'
      when 'exam_prep' then coalesce('Exam prep: ' || r.assignment_title, 'Exam prep')
      else coalesce('Review: ' || r.assignment_title, 'Review')
    end;
    kind := null;
    status := null;
    block_kind := r.kind;
    block_status := r.status;
    starts_at := r.starts_at;
    ends_at := r.ends_at;
    due_at := r.due_at;
    grade_share := null;
    minutes_remaining := case when r.status = 'planned' then r.duration_minutes else 0 end;
    planned_minutes := r.duration_minutes;
    priority := null;
    overdue := false;
    rank := v_rank;
    capacity_minutes := v_capacity;
    studied_minutes := v_studied;
    return next;
  end loop;

  -- 2. Then ranked tasks in the time that's left.
  for r in
    with logged as (
      select s.assignment_id, sum(coalesce(s.duration_minutes, 0)) as minutes
      from public.study_sessions s
      where s.user_id = v_user_id and s.assignment_id is not null
      group by s.assignment_id
    ),
    candidates as (
      select
        a.id, a.course_id, c.name as course_name, a.title, a.kind, a.status, a.due_at,
        coalesce(gs.grade_share, 0) as grade_share,
        greatest(coalesce(a.estimated_minutes, public.default_task_minutes(a.kind)) - coalesce(l.minutes, 0), 0)::integer as minutes_remaining
      from public.assignments a
      join public.courses c on c.id = a.course_id
      left join public.assignment_grade_shares gs on gs.assignment_id = a.id
      left join logged l on l.assignment_id = a.id
      where c.user_id = v_user_id
        and c.archived_at is null
        and a.status in ('todo', 'in_progress')
        and (a.due_at is null or a.due_at between v_day_start - interval '7 days' and v_day_end + interval '30 days')
    )
    select
      cand.*,
      public.task_priority(cand.grade_share, cand.due_at, v_now, cand.minutes_remaining, cand.status, coalesce(v_daily, 120)) as score
    from candidates cand
    where cand.minutes_remaining > 0
    order by score desc, cand.due_at nulls last, cand.title
  loop
    exit when v_left <= 0;
    -- Today's fair share of the task: everything if it's due by the end of today,
    -- otherwise the remaining minutes spread over the days left (at least 25 minutes
    -- so work sessions stay meaningful).
    if r.due_at is null then
      v_planned := least(r.minutes_remaining, 30);
    elsif r.due_at <= v_day_end then
      v_planned := r.minutes_remaining;
    else
      v_planned := least(
        r.minutes_remaining,
        greatest(25, ceil(r.minutes_remaining / greatest(1, ceil(extract(epoch from (r.due_at - v_day_start)) / 86400)))::integer)
      );
    end if;
    v_planned := least(v_planned, v_left);
    continue when v_planned < 15 and v_planned < r.minutes_remaining; -- too small a slot to be useful
    v_left := v_left - v_planned;
    v_rank := v_rank + 1;

    item_type := 'task';
    item_id := r.id;
    assignment_id := r.id;
    course_id := r.course_id;
    course_name := r.course_name;
    title := r.title;
    kind := r.kind;
    status := r.status;
    block_kind := null;
    block_status := null;
    starts_at := null;
    ends_at := null;
    due_at := r.due_at;
    grade_share := round(r.grade_share, 2);
    minutes_remaining := r.minutes_remaining;
    planned_minutes := v_planned;
    priority := r.score;
    overdue := r.due_at is not null and r.due_at < v_now;
    rank := v_rank;
    capacity_minutes := v_capacity;
    studied_minutes := v_studied;
    return next;
  end loop;
end;
$$;

revoke execute on function public.get_today_feed(date) from public, anon;
grant execute on function public.get_today_feed(date) to authenticated;

-- ==== 20260924004400_google_calendar.sql
-- Study system, part 4 (prompt 74): two-way Google Calendar sync. StudyPulse pushes study
-- blocks and deadlines to a dedicated calendar it creates in the student's account, and
-- reads their free/busy so the scheduler plans around their other commitments. OAuth
-- tokens live only in Vault; every function that touches them is service-role only.

-- In-flight authorizations: only a hash of the state, single use, 10 minutes.
create table public.google_oauth_states (
  state_hash text primary key check (state_hash ~ '^[0-9a-f]{64}$'),
  user_id uuid not null references public.profiles (id) on delete cascade,
  expires_at timestamptz not null default now() + interval '10 minutes'
);
alter table public.google_oauth_states enable row level security;
revoke all on public.google_oauth_states from anon, authenticated;

create table public.google_calendar_connections (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  -- The dedicated "StudyPulse" calendar, created on connect (recreated if deleted).
  calendar_id text,
  access_token_secret_id uuid not null,
  refresh_token_secret_id uuid,
  access_token_expires_at timestamptz,
  status public.lms_connection_status not null default 'active',
  push_enabled boolean not null default true,
  read_busy boolean not null default true,
  last_error text,
  connected_at timestamptz not null default now(),
  last_synced_at timestamptz,
  updated_at timestamptz not null default now()
);

create trigger google_calendar_connections_set_updated_at before update on public.google_calendar_connections
for each row execute function public.set_updated_at();

alter table public.google_calendar_connections enable row level security;
revoke all on public.google_calendar_connections from anon, authenticated;
grant select (user_id, status, push_enabled, read_busy, last_error, connected_at, last_synced_at)
  on public.google_calendar_connections to authenticated;
-- Students choose what syncs; nothing else is client-writable.
grant update (push_enabled, read_busy) on public.google_calendar_connections to authenticated;
create policy "Users can see their Google Calendar connection"
on public.google_calendar_connections for select to authenticated
using ((select auth.uid()) = user_id);
create policy "Users can change their Google Calendar sync options"
on public.google_calendar_connections for update to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

-- Which Google event holds which StudyPulse item ("block:<id>" / "due:<id>").
create table public.google_calendar_events (
  user_id uuid not null references public.profiles (id) on delete cascade,
  item_key text not null check (item_key ~ '^(block|due):[0-9a-f-]{36}$'),
  event_id text not null,
  content_hash text not null,
  updated_at timestamptz not null default now(),
  primary key (user_id, item_key),
  -- Disconnecting forgets the map too.
  constraint google_calendar_events_connection_fkey foreign key (user_id)
    references public.google_calendar_connections (user_id) on delete cascade
);
alter table public.google_calendar_events enable row level security;
revoke all on public.google_calendar_events from anon, authenticated;

-- Busy time read from the student's calendars (start/end only, never event details).
create table public.external_busy_times (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  source text not null default 'google' check (source in ('google')),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  fetched_at timestamptz not null default now(),
  constraint external_busy_times_positive check (ends_at > starts_at)
);
create index external_busy_times_user_idx on public.external_busy_times (user_id, starts_at);
alter table public.external_busy_times enable row level security;
revoke all on public.external_busy_times from anon;
revoke insert, update, delete on public.external_busy_times from authenticated;
create policy "Users can see their busy times"
on public.external_busy_times for select to authenticated
using ((select auth.uid()) = user_id);

-- Tokens go with the connection.
create or replace function private.google_delete_secrets()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.vault_delete(array[old.access_token_secret_id, old.refresh_token_secret_id]);
  return old;
end;
$$;
revoke execute on function private.google_delete_secrets() from public, anon, authenticated;
create trigger google_calendar_connections_delete_secrets after delete on public.google_calendar_connections
for each row execute function private.google_delete_secrets();

-- Service-role API -------------------------------------------------------------------------

create or replace function public.gcal_begin_oauth(p_user_id uuid, p_state_hash text)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.google_oauth_states where expires_at < now();
  insert into public.google_oauth_states (state_hash, user_id) values (p_state_hash, p_user_id);
$$;

create or replace function public.gcal_consume_oauth_state(p_state_hash text)
returns uuid
language sql
security definer
set search_path = ''
as $$
  delete from public.google_oauth_states s
  where s.state_hash = p_state_hash and s.expires_at > now()
  returning s.user_id;
$$;

create or replace function public.gcal_save_connection(
  p_user_id uuid, p_access_token text, p_refresh_token text default null, p_expires_at timestamptz default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_conn public.google_calendar_connections;
  v_access uuid;
  v_refresh uuid;
begin
  select * into v_conn from public.google_calendar_connections where user_id = p_user_id for update;
  v_access := private.vault_put(v_conn.access_token_secret_id, p_access_token, null);
  v_refresh := case
    when p_refresh_token is null then v_conn.refresh_token_secret_id
    else private.vault_put(v_conn.refresh_token_secret_id, p_refresh_token, null)
  end;
  insert into public.google_calendar_connections as c (
    user_id, access_token_secret_id, refresh_token_secret_id, access_token_expires_at, status, last_error, connected_at
  ) values (p_user_id, v_access, v_refresh, p_expires_at, 'active', null, now())
  on conflict (user_id) do update set
    access_token_secret_id = excluded.access_token_secret_id,
    refresh_token_secret_id = excluded.refresh_token_secret_id,
    access_token_expires_at = excluded.access_token_expires_at,
    status = 'active',
    last_error = null;
end;
$$;

create or replace function public.gcal_update_tokens(
  p_user_id uuid, p_access_token text, p_expires_at timestamptz default null, p_refresh_token text default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.google_calendar_connections c set
    access_token_secret_id = private.vault_put(c.access_token_secret_id, p_access_token, null),
    refresh_token_secret_id = case when p_refresh_token is null then c.refresh_token_secret_id
      else private.vault_put(c.refresh_token_secret_id, p_refresh_token, null) end,
    access_token_expires_at = p_expires_at
  where c.user_id = p_user_id;
$$;

create or replace function public.gcal_credentials(p_user_id uuid)
returns table (
  user_id uuid, status public.lms_connection_status, calendar_id text, push_enabled boolean,
  read_busy boolean, access_token text, refresh_token text, access_token_expires_at timestamptz,
  timezone text
)
language sql
stable
security definer
set search_path = ''
as $$
  select c.user_id, c.status, c.calendar_id, c.push_enabled, c.read_busy,
         private.vault_get(c.access_token_secret_id), private.vault_get(c.refresh_token_secret_id),
         c.access_token_expires_at, p.timezone
  from public.google_calendar_connections c
  join public.profiles p on p.id = c.user_id
  where c.user_id = p_user_id;
$$;

-- A new calendar id (first connect, or the old one was deleted) invalidates the event map.
create or replace function public.gcal_set_calendar(p_user_id uuid, p_calendar_id text default null)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.google_calendar_events where user_id = p_user_id;
  update public.google_calendar_connections set calendar_id = p_calendar_id where user_id = p_user_id;
$$;

create or replace function public.gcal_mark_needs_reauth(p_user_id uuid, p_error text)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.google_calendar_connections
  set status = 'needs_reauth', last_error = left(p_error, 500)
  where user_id = p_user_id;
$$;

create or replace function public.gcal_record_sync(p_user_id uuid, p_error text default null)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.google_calendar_connections
  set last_synced_at = case when p_error is null then now() else last_synced_at end,
      last_error = left(p_error, 500)
  where user_id = p_user_id;
$$;

-- Replaces the user's busy times in a window. Returns whether anything changed, so the
-- caller only replans when it matters.
create or replace function public.gcal_replace_busy(p_user_id uuid, p_from timestamptz, p_to timestamptz, p_busy jsonb)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_before text;
  v_after text;
begin
  if jsonb_typeof(p_busy) <> 'array' or jsonb_array_length(p_busy) > 2000 then
    raise exception 'p_busy must be an array of at most 2000 ranges' using errcode = '22023';
  end if;
  select string_agg(starts_at::text || '/' || ends_at::text, ',' order by starts_at) into v_before
  from public.external_busy_times
  where user_id = p_user_id and source = 'google' and ends_at > p_from and starts_at < p_to;

  delete from public.external_busy_times
  where user_id = p_user_id and source = 'google' and ends_at > p_from and starts_at < p_to;
  insert into public.external_busy_times (user_id, source, starts_at, ends_at)
  select p_user_id, 'google', (b ->> 'startsAt')::timestamptz, (b ->> 'endsAt')::timestamptz
  from jsonb_array_elements(p_busy) b
  where (b ->> 'endsAt')::timestamptz > (b ->> 'startsAt')::timestamptz;
  -- Old ranges are no use to anyone.
  delete from public.external_busy_times where user_id = p_user_id and ends_at < now() - interval '1 day';

  select string_agg(starts_at::text || '/' || ends_at::text, ',' order by starts_at) into v_after
  from public.external_busy_times
  where user_id = p_user_id and source = 'google' and ends_at > p_from and starts_at < p_to;
  return v_before is distinct from v_after;
end;
$$;

-- Connections due for a scheduled sync: active and not synced in the last 25 minutes.
create or replace function public.gcal_connections_due(p_limit integer default 200)
returns table (user_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  select c.user_id from public.google_calendar_connections c
  where c.status = 'active' and (c.last_synced_at is null or c.last_synced_at < now() - interval '25 minutes')
  order by c.last_synced_at nulls first
  limit p_limit;
$$;

-- Disconnect: the caller's own connection (or any, for the service role). Busy times go too.
create or replace function public.gcal_disconnect(p_user_id uuid)
returns boolean
language sql
security definer
set search_path = ''
as $$
  with deleted as (
    delete from public.google_calendar_connections
    where user_id = p_user_id
      and (user_id = (select auth.uid()) or (select auth.role()) = 'service_role')
    returning user_id
  ), busy as (
    delete from public.external_busy_times b using deleted d where b.user_id = d.user_id
  )
  select exists (select 1 from deleted);
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.gcal_begin_oauth(uuid, text)',
    'public.gcal_consume_oauth_state(text)',
    'public.gcal_save_connection(uuid, text, text, timestamptz)',
    'public.gcal_update_tokens(uuid, text, timestamptz, text)',
    'public.gcal_credentials(uuid)',
    'public.gcal_set_calendar(uuid, text)',
    'public.gcal_mark_needs_reauth(uuid, text)',
    'public.gcal_record_sync(uuid, text)',
    'public.gcal_replace_busy(uuid, timestamptz, timestamptz, jsonb)',
    'public.gcal_connections_due(integer)'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;
revoke execute on function public.gcal_disconnect(uuid) from public, anon;
grant execute on function public.gcal_disconnect(uuid) to authenticated, service_role;

select cron.schedule('google-calendar-sync', '*/30 * * * *', $$ select private.invoke_edge_function('google-calendar-sync') $$);

-- ==== 20260924004500_assignment_resources.sql
-- Study system, part 5 (prompt 75): per-assignment study links: Khan Academy lessons,
-- NotebookLM notebooks, Anki decks (AnkiWeb shared decks), or any other https link.
-- course_id is carried with a composite key so RLS and account deletion follow the course.

create table public.assignment_resources (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null,
  course_id uuid not null references public.courses (id) on delete cascade,
  kind text not null check (kind in ('khan_academy', 'notebooklm', 'anki_deck', 'other')),
  url text not null check (char_length(url) <= 2048),
  title text check (char_length(trim(title)) between 1 and 200),
  position smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint assignment_resources_assignment_fkey foreign key (assignment_id, course_id)
    references public.assignments (id, course_id) on delete cascade,
  constraint assignment_resources_unique_url unique (assignment_id, url),
  -- https only, and the host has to match the kind (so a "Khan Academy" badge is honest).
  constraint assignment_resources_url_matches_kind check (
    url ~ '^https://[^/\s@]+(/\S*)?$' and case kind
      when 'khan_academy' then url ~* '^https://([a-z0-9-]+\.)?khanacademy\.org(/|$)'
      when 'notebooklm' then url ~* '^https://notebooklm\.google\.com(/|$)'
      when 'anki_deck' then url ~* '^https://ankiweb\.net/shared/'
      else true
    end
  )
);

create index assignment_resources_assignment_idx on public.assignment_resources (assignment_id, position);
create index assignment_resources_course_idx on public.assignment_resources (course_id);

create trigger assignment_resources_set_updated_at before update on public.assignment_resources
for each row execute function public.set_updated_at();

-- At most 20 links per assignment.
create or replace function private.limit_assignment_resources()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.assignment_resources where assignment_id = new.assignment_id) >= 20 then
    raise exception 'An assignment can have at most 20 links' using errcode = '23514';
  end if;
  return new;
end;
$$;
revoke execute on function private.limit_assignment_resources() from public, anon, authenticated;
create trigger assignment_resources_limit before insert on public.assignment_resources
for each row execute function private.limit_assignment_resources();

alter table public.assignment_resources enable row level security;

create policy "Users can view links in their courses"
on public.assignment_resources for select to authenticated
using ((select private.owns_course(course_id)));

create policy "Users can add links in their courses"
on public.assignment_resources for insert to authenticated
with check ((select private.owns_course(course_id)));

create policy "Users can update links in their courses"
on public.assignment_resources for update to authenticated
using ((select private.owns_course(course_id)))
with check ((select private.owns_course(course_id)));

create policy "Users can delete links in their courses"
on public.assignment_resources for delete to authenticated
using ((select private.owns_course(course_id)));

revoke all on public.assignment_resources from anon;

-- ==== 20260924004600_calendar.sql
-- Calendar data for a range of local dates: assignment due dates and study blocks, each
-- tagged with its calendar date in the user's timezone, plus course chips. Runs as the
-- caller, so RLS applies. Ranges are capped at 62 days (a month grid is at most 42).

create or replace function public.get_calendar(p_from date, p_to date)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_tz text;
  v_start timestamptz;
  v_end timestamptz;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'p_to must be on or after p_from' using errcode = '22023';
  end if;
  if p_to - p_from > 62 then
    raise exception 'calendar range is limited to 62 days' using errcode = '22023';
  end if;

  select timezone into v_tz from public.profiles where id = v_user;
  v_start := p_from::timestamp at time zone v_tz;
  v_end := (p_to + 1)::timestamp at time zone v_tz;

  return jsonb_build_object(
    'timezone', v_tz,
    'today', (now() at time zone v_tz)::date,
    'from', p_from,
    'to', p_to,
    'items', coalesce((
      select jsonb_agg(i order by i ->> 'date', i ->> 'starts_at', i ->> 'title')
      from (
        select jsonb_build_object(
          'type', 'due',
          'id', a.id,
          'title', a.title,
          'kind', a.kind,
          'status', a.status,
          'course_id', a.course_id,
          'date', (a.due_at at time zone v_tz)::date,
          'starts_at', a.due_at,
          'ends_at', null,
          'overdue', a.status in ('todo', 'in_progress') and a.due_at < now()
        ) as i
        from public.assignments a
        join public.courses c on c.id = a.course_id and c.archived_at is null
        where a.due_at >= v_start and a.due_at < v_end
        union all
        select jsonb_build_object(
          'type', 'study',
          'id', b.id,
          'title', coalesce(a.title, c.name),
          'kind', b.kind,
          'status', b.status,
          'course_id', b.course_id,
          'date', (b.starts_at at time zone v_tz)::date,
          'starts_at', b.starts_at,
          'ends_at', b.ends_at,
          'overdue', false
        )
        from public.study_blocks b
        join public.courses c on c.id = b.course_id and c.archived_at is null
        left join public.assignments a on a.id = b.assignment_id
        where b.starts_at >= v_start and b.starts_at < v_end
      ) x
    ), '[]'::jsonb),
    'courses', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'code', coalesce(c.code, c.name), 'name', c.name, 'color', c.color) order by c.name)
      from public.courses c
      where c.archived_at is null
    ), '[]'::jsonb)
  );
end;
$$;

revoke execute on function public.get_calendar(date, date) from public, anon;
grant execute on function public.get_calendar(date, date) to authenticated;

-- ==== 20260924004700_courses_overview.sql
-- Courses screen (UI prompt 83): one call for the course cards (and the user's timezone). Current grade and
-- letter use the same SQL as everywhere else; runs as the caller, so RLS applies.
create or replace function public.get_courses_overview()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'timezone', (select timezone from public.profiles where id = v_user),
    'courses', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'code', c.code,
      'color', c.color,
      'instructor', c.instructor,
      'target_grade', c.target_grade,
      'current_grade', round(g.current, 2),
      'letter', public.letter_for(g.current, c.letter_scale),
      'open_count', (select count(*) from public.assignments a
                     where a.course_id = c.id and a.status in ('todo', 'in_progress')),
      'next_due', (
        select jsonb_build_object('id', a.id, 'title', a.title, 'kind', a.kind, 'due_at', a.due_at)
        from public.assignments a
        where a.course_id = c.id and a.status in ('todo', 'in_progress') and a.due_at >= now()
        order by a.due_at
        limit 1
      )
    ) order by coalesce(c.code, c.name))
    from public.courses c
    cross join lateral (select public.course_current_grade(c.id) as current) g
    where c.archived_at is null
  ), '[]'::jsonb));
end;
$$;

revoke execute on function public.get_courses_overview() from public, anon;
grant execute on function public.get_courses_overview() to authenticated;

-- ==== 20260924004800_replan_once_per_day.sql
-- Fix F1-F4: the hourly nightly-replan job replans each user at most once per local
-- day, whatever their UTC offset (+5:30, +5:45, -3:30, ...) and across DST changes.
--
-- Before: users_due_for_replan picked users whose local hour was exactly 3 on this run:
--   where extract(hour from p_now at time zone p.timezone) = p_local_hour
-- That already included half-hour and 45-minute zones (the job runs at minute 5), but
-- nothing stopped a retried or duplicate run from replanning the same user again, a
-- zone that springs forward at 3 AM (e.g. Europe/Athens) never had a local hour 3 that
-- day (skipped), and one that falls back at 4 AM had it twice (replanned twice).
--
-- After: claim_users_for_replan picks users whose local hour is 3 or later and whose
-- last_replanned_on is before their local today, and stamps last_replanned_on in the
-- same statement (rows locked, skip locked), so concurrent runs can't both claim a
-- user. A day whose 3 AM never happened is caught up at the next hourly run. If a
-- replan fails, the job releases the claim and a later run retries it that day.

alter table public.profiles add column last_replanned_on date;

drop function public.users_due_for_replan(integer, timestamptz);

create or replace function public.claim_users_for_replan(
  p_local_hour integer default 3,
  p_now timestamptz default now(),
  p_limit integer default 5000
)
returns table (user_id uuid, timezone text, local_date date, previous_date date)
language sql
volatile
security definer
set search_path = ''
as $$
  with due as (
    select p.id, (p_now at time zone p.timezone)::date as local_date, p.last_replanned_on
    from public.profiles p
    where extract(hour from p_now at time zone p.timezone) >= p_local_hour
      and (p.last_replanned_on is null or p.last_replanned_on < (p_now at time zone p.timezone)::date)
      and (
        exists (
          select 1 from public.assignments a
          join public.courses c on c.id = a.course_id
          where c.user_id = p.id and c.archived_at is null
            and a.status in ('todo', 'in_progress')
            and a.due_at between p_now and p_now + interval '28 days'
        )
        or exists (
          select 1 from public.study_blocks b
          where b.user_id = p.id and b.status = 'planned' and b.starts_at > p_now
        )
      )
    order by p.id
    limit p_limit
    for update of p skip locked
  )
  update public.profiles p
  set last_replanned_on = d.local_date
  from due d
  where p.id = d.id
  returning p.id, p.timezone, d.local_date, d.last_replanned_on;
$$;

-- Undo a claim whose replan failed or was deferred, so a later run that day retries it.
create or replace function public.release_replan_claim(p_user_id uuid, p_local_date date, p_previous_date date default null)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.profiles
  set last_replanned_on = p_previous_date
  where id = p_user_id and last_replanned_on = p_local_date;
$$;

revoke execute on function public.claim_users_for_replan(integer, timestamptz, integer) from public, anon, authenticated;
revoke execute on function public.release_replan_claim(uuid, date, date) from public, anon, authenticated;
grant execute on function public.claim_users_for_replan(integer, timestamptz, integer) to service_role;
grant execute on function public.release_replan_claim(uuid, date, date) to service_role;

-- ==== 20260924004900_priority_bands.sql
-- Fixes F5-F7: task_priority mirrors packages/core/src/priority (parity-tested on every
-- fixture). The 0-1 blend of impact and urgency is placed in a band:
--   90-100 overdue and still open; 10-90 dated work with a grade share; 0-10 undated
--   work or work with no category/weight; 0 done or skipped.
-- Missing or non-finite inputs (null, NaN, infinite dates) count as missing, so the
-- result is always a number from 0 to 100.
create or replace function public.task_priority(
  p_grade_share numeric,
  p_due_at timestamptz,
  p_now timestamptz,
  p_minutes_remaining numeric,
  p_status public.assignment_status,
  p_daily_minutes numeric default 120
)
returns numeric
language plpgsql
immutable
parallel safe
set search_path = ''
as $$
declare
  v_share numeric := case when p_grade_share is null or p_grade_share = 'NaN' then 0 else greatest(0, p_grade_share) end;
  v_minutes numeric := case when p_minutes_remaining is null or p_minutes_remaining = 'NaN' then 0
                            else greatest(0, p_minutes_remaining) end;
  v_daily numeric := case when p_daily_minutes is null or p_daily_minutes = 'NaN' or p_daily_minutes <= 0 then 120
                          else p_daily_minutes end;
  v_dated boolean := p_due_at is not null and isfinite(p_due_at);
  v_impact numeric;
  v_days numeric;
  v_urgency numeric;
  v_base numeric;
  v_min numeric;
  v_max numeric;
begin
  if p_status in ('done', 'skipped') then
    return 0;
  end if;
  -- Infinite share (numeric 'Infinity') saturates like any share >= 30.
  v_impact := sqrt(least(1, v_share / 30.0));
  if not v_dated then
    v_urgency := 0.05;
  else
    v_days := extract(epoch from (p_due_at - p_now)) / 86400.0;
    v_urgency := case when v_days <= 0 then 1 else 1 / (1 + greatest(0, v_days - v_minutes / v_daily)) end;
  end if;
  v_base := 0.55 * v_impact + 0.45 * v_urgency;
  if p_status = 'in_progress' then
    v_base := v_base * 1.1;
  end if;
  v_base := least(1, v_base);
  if v_dated and v_days < 0 then
    v_min := 90; v_max := 100;        -- overdue and still open
  elsif v_dated and v_share > 0 then
    v_min := 10; v_max := 90;         -- dated, counts toward the grade
  else
    v_min := 0; v_max := 10;          -- undated or unweighted
  end if;
  return round(v_min + (v_max - v_min) * v_base, 3);
end;
$$;

-- ==== 20260924005000_focus_overview.sql
-- Focus screen (UI prompt 84): one call for the metric cards (today's minutes and the
-- streak, both in the user's timezone), the running session, what the timer is linked
-- to, things to link it to, and recent session history. Runs as the caller, so RLS applies.
--
-- Streak: consecutive local days with any focus time, counted back from today. A streak
-- that ended yesterday is still alive until today is over (studying today extends it).
create or replace function public.get_focus_overview(
  p_assignment_id uuid default null,
  p_block_id uuid default null,
  p_history int default 20
)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_tz text;
  v_today date;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_streak int;
  v_linked jsonb;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select coalesce(timezone, 'UTC') into v_tz from public.profiles where id = v_user;
  v_today := (now() at time zone v_tz)::date;
  v_day_start := v_today::timestamp at time zone v_tz;
  v_day_end := (v_today + 1)::timestamp at time zone v_tz;

  with days as (
    select distinct (s.started_at at time zone v_tz)::date as d
    from public.study_sessions s
    where s.user_id = v_user
      and s.started_at >= now() - interval '400 days'
      and (s.started_at at time zone v_tz)::date <= v_today
      and (s.ended_at is null or s.ended_at - s.started_at >= interval '1 minute')
  ),
  runs as (
    -- Consecutive dates, newest first, share d + row_number.
    select d, d + (row_number() over (order by d desc))::int as grp from days
  ),
  latest as (select d, grp from runs order by d desc limit 1)
  select case when l.d >= v_today - 1 then (select count(*) from runs r where r.grp = l.grp) else 0 end
  into v_streak
  from latest l;

  -- What the timer is for: a study block (e.g. from Today's reviews) or an assignment.
  if p_block_id is not null then
    select jsonb_build_object(
      'block_id', b.id, 'block_kind', b.kind, 'block_minutes', b.duration_minutes,
      'assignment_id', a.id, 'title', coalesce(a.title, 'Study ' || coalesce(c.code, c.name)),
      'due_at', a.due_at, 'course_id', c.id, 'course_code', c.code,
      'course_name', c.name, 'course_color', c.color)
    into v_linked
    from public.study_blocks b
    join public.courses c on c.id = b.course_id
    left join public.assignments a on a.id = b.assignment_id
    where b.id = p_block_id;
  elsif p_assignment_id is not null then
    select jsonb_build_object(
      'block_id', null, 'block_kind', null, 'block_minutes', null,
      'assignment_id', a.id, 'title', a.title, 'due_at', a.due_at, 'course_id', c.id,
      'course_code', c.code, 'course_name', c.name, 'course_color', c.color)
    into v_linked
    from public.assignments a
    join public.courses c on c.id = a.course_id
    where a.id = p_assignment_id;
  end if;

  return jsonb_build_object(
    'timezone', v_tz,
    'today', v_today,
    'today_minutes', coalesce((
      select floor(sum(extract(epoch from
        least(coalesce(s.ended_at, now()), v_day_end) - greatest(s.started_at, v_day_start))) / 60)::int
      from public.study_sessions s
      where s.user_id = v_user
        and s.started_at < v_day_end
        and coalesce(s.ended_at, now()) > v_day_start
    ), 0),
    'streak_days', coalesce(v_streak, 0),
    'running', (
      select jsonb_build_object(
        'id', s.id, 'started_at', s.started_at, 'assignment_id', s.assignment_id,
        'title', coalesce(a.title, 'Study ' || coalesce(c.code, c.name)),
        'course_id', c.id, 'course_code', c.code, 'course_name', c.name, 'course_color', c.color)
      from public.study_sessions s
      join public.courses c on c.id = s.course_id
      left join public.assignments a on a.id = s.assignment_id
      where s.user_id = v_user and s.ended_at is null
      limit 1
    ),
    'linked', v_linked,
    'choices', coalesce((
      select jsonb_agg(x.item order by x.due_at nulls last, x.title)
      from (
        select a.title, a.due_at, jsonb_build_object(
          'assignment_id', a.id, 'title', a.title, 'due_at', a.due_at, 'course_id', c.id,
          'course_code', c.code, 'course_name', c.name, 'course_color', c.color) as item
        from public.assignments a
        join public.courses c on c.id = a.course_id
        where c.archived_at is null and a.status in ('todo', 'in_progress')
        order by a.due_at nulls last, a.title
        limit 30
      ) x
    ), '[]'::jsonb),
    'courses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'code', c.code, 'name', c.name, 'color', c.color) order by coalesce(c.code, c.name))
      from public.courses c
      where c.archived_at is null
    ), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(h.item order by h.started_at desc)
      from (
        select s.started_at, jsonb_build_object(
          'id', s.id, 'started_at', s.started_at, 'ended_at', s.ended_at,
          'minutes', s.duration_minutes, 'assignment_id', s.assignment_id,
          'title', coalesce(a.title, 'Study ' || coalesce(c.code, c.name)),
          'course_id', c.id, 'course_code', c.code, 'course_name', c.name,
          'course_color', c.color) as item
        from public.study_sessions s
        join public.courses c on c.id = s.course_id
        left join public.assignments a on a.id = s.assignment_id
        where s.user_id = v_user and s.ended_at is not null and s.duration_minutes >= 1
        order by s.started_at desc
        limit least(greatest(coalesce(p_history, 20), 1), 100)
      ) h
    ), '[]'::jsonb)
  );
end;
$$;

revoke execute on function public.get_focus_overview(uuid, uuid, int) from public, anon;
grant execute on function public.get_focus_overview(uuid, uuid, int) to authenticated;

-- ==== 20260924005100_stats_overview.sql
-- Stats screen (UI prompt 85): focus minutes against grade per course, in one call.
-- Weeks start on Monday in the user's timezone, and a session counts on the local day
-- it started (the same rule as get_today_overview). Runs as the caller, so RLS applies.
create or replace function public.get_stats_overview(p_weeks int default 4)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_tz text;
  v_today date;
  v_week_start date;
  v_weeks int := least(greatest(coalesce(p_weeks, 4), 1), 26);
  v_period_start date;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select coalesce(timezone, 'UTC') into v_tz from public.profiles where id = v_user;
  v_today := (now() at time zone v_tz)::date;
  v_week_start := date_trunc('week', v_today::timestamp)::date;
  v_period_start := v_week_start - (v_weeks - 1) * 7;

  return (
    with sessions as (
      select s.course_id, (s.started_at at time zone v_tz)::date as local_day, s.duration_minutes as minutes
      from public.study_sessions s
      where s.user_id = v_user
        and s.ended_at is not null
        and s.started_at >= (v_period_start - 1)::timestamp at time zone v_tz
        and (s.started_at at time zone v_tz)::date between v_period_start and v_today
    ),
    courses as (
      select c.id, c.code, c.name, c.color, c.target_grade,
             round(g.current, 2) as current_grade,
             public.letter_for(g.current, c.letter_scale) as letter,
             coalesce((select sum(x.minutes) from sessions x where x.course_id = c.id), 0)::int as focus_minutes
      from public.courses c
      cross join lateral (select public.course_current_grade(c.id) as current) g
      where c.archived_at is null
    )
    select jsonb_build_object(
      'timezone', v_tz,
      'today', v_today,
      'week_start', v_week_start,
      'period_start', v_period_start,
      'weeks', v_weeks,
      'this_week_minutes', coalesce((select sum(minutes) from sessions where local_day >= v_week_start), 0),
      'weekly', (
        select jsonb_agg(jsonb_build_object(
          'week_start', w.d,
          'minutes', coalesce((select sum(x.minutes) from sessions x
                               where x.local_day between w.d and w.d + 6), 0)
        ) order by w.d)
        from (select ts::date as d
              from generate_series(v_period_start, v_week_start, interval '7 days') as g(ts)) w
      ),
      -- Plain mean of the current grades of courses that have one.
      'average_grade', (select round(avg(current_grade), 2) from courses where current_grade is not null),
      'courses', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', id, 'code', code, 'name', name, 'color', color, 'target_grade', target_grade,
          'current_grade', current_grade, 'letter', letter, 'focus_minutes', focus_minutes
        ) order by coalesce(code, name))
        from courses
      ), '[]'::jsonb)
    )
  );
end;
$$;

revoke execute on function public.get_stats_overview(int) from public, anon;
grant execute on function public.get_stats_overview(int) to authenticated;

-- ==== 20260924005200_settings_onboarding.sql
-- Onboarding and Settings (UI prompt 86).
--
-- profiles.onboarded_at: null until the user finishes onboarding (name, timezone, study
-- time). Accounts that existed before this migration count as onboarded.
alter table public.profiles add column onboarded_at timestamptz;
update public.profiles set onboarded_at = created_at where onboarded_at is null;

-- The post-class card task toggle (prompt 71) is the user's own setting.
grant update (card_tasks_enabled) on public.profiles to authenticated;

-- Everything the Settings screen shows, in one call (the email comes from the session). Runs as the caller, so RLS applies.
create or replace function public.get_settings()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  return (
    select jsonb_build_object(
      'profile', jsonb_build_object(
        'display_name', p.display_name,
        'school', p.school,
        'timezone', p.timezone,
        'daily_study_minutes', p.daily_study_minutes,
        'study_start_time', to_char(p.study_start_time, 'HH24:MI'),
        'card_tasks_enabled', p.card_tasks_enabled,
        'plan_tier', p.plan_tier,
        'onboarded_at', p.onboarded_at
      ),
      'notifications', (
        select jsonb_build_object(
          'push_enabled', n.push_enabled,
          'email_digest_enabled', n.email_digest_enabled,
          'remind_24h', n.remind_24h,
          'remind_2h', n.remind_2h,
          'exam_countdown', n.exam_countdown,
          'morning_digest', n.morning_digest,
          'morning_digest_time', to_char(n.morning_digest_time, 'HH24:MI'),
          'quiet_hours_enabled', n.quiet_hours_enabled,
          'quiet_hours_start', to_char(n.quiet_hours_start, 'HH24:MI'),
          'quiet_hours_end', to_char(n.quiet_hours_end, 'HH24:MI'),
          'daily_cap', n.daily_cap
        )
        from public.notification_prefs n where n.user_id = v_user
      ),
      -- Devices that can receive reminders, so the screen can say where they go.
      'devices', jsonb_build_object(
        'mobile', (select count(*) from public.notification_tokens t
                   where t.user_id = v_user and t.provider = 'expo' and t.invalidated_at is null),
        'web', (select count(*) from public.notification_tokens t
                where t.user_id = v_user and t.provider = 'web_push' and t.invalidated_at is null)
      )
    )
    from public.profiles p
    where p.id = v_user
  );
end;
$$;

-- Finishes onboarding: saves the answers and stamps onboarded_at (first time only).
-- Security definer because clients can't write onboarded_at directly; it only ever
-- touches the caller's own row. Check constraints validate the name and minutes.
create or replace function public.complete_onboarding(
  p_display_name text,
  p_timezone text,
  p_daily_study_minutes int,
  p_study_start_time time
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not public.is_valid_timezone(p_timezone) then
    raise exception 'unknown timezone %', p_timezone using errcode = '22023';
  end if;
  update public.profiles
  set display_name = nullif(btrim(p_display_name), ''),
      timezone = p_timezone,
      daily_study_minutes = p_daily_study_minutes,
      study_start_time = p_study_start_time,
      onboarded_at = coalesce(onboarded_at, now())
  where id = v_user;
end;
$$;

revoke execute on function public.get_settings() from public, anon;
revoke execute on function public.complete_onboarding(text, text, int, time) from public, anon;
grant execute on function public.get_settings() to authenticated;
grant execute on function public.complete_onboarding(text, text, int, time) to authenticated;

-- ==== 20260924005300_require_live_session.sql
-- Launch safety S5: a signed-out token can't read data.
--
-- Supabase access tokens are JWTs that stay valid until they expire (up to an hour), even
-- after the user signs out everywhere. PostgREST runs this function before every API
-- request: a signed-in request whose session no longer exists in auth.sessions (signed
-- out, revoked, or the account deleted) is refused with 401. The lookup is a primary-key
-- hit, so the cost per request is negligible. Edge functions already verify tokens with
-- the auth server (getUser), which also rejects ended sessions.
-- Its own schema, so granting API roles usage here exposes nothing else.
create schema if not exists request_guard;
revoke all on schema request_guard from public;

create or replace function request_guard.require_live_session()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_claims jsonb := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  v_session uuid;
begin
  if v_claims is null or v_claims ->> 'role' is distinct from 'authenticated' then
    return; -- anon and service_role requests aren't tied to a user session
  end if;
  v_session := nullif(v_claims ->> 'session_id', '')::uuid;
  if v_session is null or not exists (select 1 from auth.sessions s where s.id = v_session) then
    raise exception 'session ended; sign in again'
      using errcode = 'PT401', hint = 'session_ended';
  end if;
end;
$$;

revoke execute on function request_guard.require_live_session() from public;
grant usage on schema request_guard to anon, authenticated;
grant execute on function request_guard.require_live_session() to anon, authenticated;

alter role authenticator set pgrst.db_pre_request = 'request_guard.require_live_session';
notify pgrst, 'reload config';

-- ==== 20260924005400_password_attempt_limit.sql
-- Launch safety S6: per-account limit on password guessing. Supabase Auth already limits
-- sign-in and sign-up requests per IP ([auth.rate_limit] in config.toml); this Auth hook
-- adds a per-email limit: 10 wrong passwords within 15 minutes lock the account's
-- password sign-in for 15 minutes. While locked, the hook answers exactly like a wrong
-- password, so a lockout never reveals whether an account exists.
--
-- Wired up in supabase/config.toml ([auth.hook.password_verification_attempt]). On hosted
-- Supabase this hook needs the Team plan; see docs/launch-checklist.md for the CAPTCHA
-- alternative.
create table private.password_attempts (
  user_id uuid primary key references auth.users (id) on delete cascade,
  failures integer not null default 0,
  window_start timestamptz not null default now(),
  locked_until timestamptz
);
alter table private.password_attempts enable row level security;

create or replace function public.hook_password_verification_attempt(event jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (event ->> 'user_id')::uuid;
  v_valid boolean := coalesce((event ->> 'valid')::boolean, false);
  v_row private.password_attempts;
  -- Same words Supabase uses for a wrong password.
  v_reject jsonb := jsonb_build_object('decision', 'reject', 'message', 'Invalid login credentials',
                                       'should_logout_user', false);
begin
  select * into v_row from private.password_attempts where user_id = v_user for update;

  if v_row.locked_until is not null and v_row.locked_until > now() then
    return v_reject;
  end if;

  if v_valid then
    delete from private.password_attempts where user_id = v_user;
    return jsonb_build_object('decision', 'continue');
  end if;

  insert into private.password_attempts (user_id, failures, window_start)
  values (v_user, 1, now())
  on conflict (user_id) do update
    set failures = case when private.password_attempts.window_start < now() - interval '15 minutes'
                        then 1 else private.password_attempts.failures + 1 end,
        window_start = case when private.password_attempts.window_start < now() - interval '15 minutes'
                            then now() else private.password_attempts.window_start end,
        locked_until = null
  returning * into v_row;

  if v_row.failures >= 10 then
    update private.password_attempts set locked_until = now() + interval '15 minutes'
    where user_id = v_user;
  end if;
  return jsonb_build_object('decision', 'continue');
end;
$$;

revoke execute on function public.hook_password_verification_attempt(jsonb) from public, anon, authenticated;
grant execute on function public.hook_password_verification_attempt(jsonb) to supabase_auth_admin;
grant usage on schema private to supabase_auth_admin;
grant select, insert, update, delete on private.password_attempts to supabase_auth_admin;

-- ==== 20260924005500_ai_daily_spend_cap.sql
-- Launch safety S7: a hard daily AI spend cap per user, on top of the count limits
-- (3/25 parses a day, 5/50 card generations). Once a user's AI cost for their local day
-- reaches the cap, new syllabus parses and card generations are refused (SPB01) until
-- their next local day, and work already queued stops before its next AI call.
--
-- Costs use the same prices as the cost alerts (ai_model_prices; unknown models at the
-- highest rate). A single parse can finish past the cap, so the most anyone can spend in
-- a day is the cap plus one request (bounded by max_tokens).

create table public.ai_daily_caps (
  plan_tier public.plan_tier primary key,
  cents integer not null check (cents > 0)
);
alter table public.ai_daily_caps enable row level security;
revoke all on public.ai_daily_caps from anon, authenticated;

-- Change without a deploy: update public.ai_daily_caps set cents = ... where plan_tier = ...
insert into public.ai_daily_caps (plan_tier, cents) values ('free', 100), ('pro', 500);

-- AI cost (cents) of a user's parses and card generations since their local midnight.
create or replace function private.ai_spent_today_cents(p_user_id uuid)
returns numeric
language sql
stable
security definer
set search_path = ''
as $$
  with day as (
    select date_trunc('day', now() at time zone p.timezone) at time zone p.timezone as start
    from public.profiles p where p.id = p_user_id
  )
  select coalesce((
    select sum(private.ai_usage_cost_cents(u.ai_usage))
    from public.syllabus_uploads u, day
    where u.user_id = p_user_id and u.created_at >= day.start
  ), 0) + coalesce((
    select sum(private.ai_usage_cost_cents(g.ai_usage))
    from public.card_generations g, day
    where g.user_id = p_user_id and g.created_at >= day.start
  ), 0);
$$;

create or replace function private.ai_daily_cap_cents(p_user_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select c.cents from public.profiles p join public.ai_daily_caps c on c.plan_tier = p.plan_tier
     where p.id = p_user_id),
    (select min(cents) from public.ai_daily_caps)
  );
$$;

-- Refuses new AI work once today's spend reaches the cap.
create or replace function private.enforce_ai_daily_cap()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if private.ai_spent_today_cents(new.user_id) >= private.ai_daily_cap_cents(new.user_id) then
    raise exception 'You''ve reached today''s limit for AI features. It resets at midnight.'
      using errcode = 'SPB01', hint = 'ai_budget_exceeded';
  end if;
  return new;
end;
$$;

create trigger syllabus_uploads_enforce_ai_cap
before insert on public.syllabus_uploads
for each row execute function private.enforce_ai_daily_cap();

create trigger card_generations_enforce_ai_cap
before insert on public.card_generations
for each row execute function private.enforce_ai_daily_cap();

-- For the edge functions, right before each AI call (service role only).
create or replace function public.ai_budget_status(p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'spent_cents', round(private.ai_spent_today_cents(p_user_id), 4),
    'cap_cents', private.ai_daily_cap_cents(p_user_id),
    'exceeded', private.ai_spent_today_cents(p_user_id) >= private.ai_daily_cap_cents(p_user_id)
  );
$$;

revoke execute on function private.ai_spent_today_cents(uuid) from public, anon, authenticated;
revoke execute on function private.ai_daily_cap_cents(uuid) from public, anon, authenticated;
revoke execute on function private.enforce_ai_daily_cap() from public, anon, authenticated;
revoke execute on function public.ai_budget_status(uuid) from public, anon, authenticated;
grant execute on function public.ai_budget_status(uuid) to service_role;

-- ==== 20260924005600_foreign_key_indexes.sql
-- Launch safety S8: every foreign key gets an index, so deletes of parents (account
-- deletion, course deletion) and joins don't scan whole tables.
create index if not exists courses_lms_connection_idx on public.courses (lms_connection_id);
create index if not exists syllabus_uploads_course_idx on public.syllabus_uploads (course_id);
create index if not exists study_blocks_rescheduled_from_idx on public.study_blocks (rescheduled_from);
create index if not exists notification_log_assignment_idx on public.notification_log (assignment_id);
create index if not exists notification_log_token_idx on public.notification_log (token_id);
create index if not exists billing_events_user_idx on public.billing_events (user_id);
create index if not exists lms_oauth_states_institution_idx on public.lms_oauth_states (institution_id);
create index if not exists lms_oauth_states_user_idx on public.lms_oauth_states (user_id);
create index if not exists lms_connections_institution_idx on public.lms_connections (institution_id);
create index if not exists card_generations_assignment_idx on public.card_generations (assignment_id);
create index if not exists card_generations_course_idx on public.card_generations (course_id);
create index if not exists google_oauth_states_user_idx on public.google_oauth_states (user_id);

-- ==== 20260924005700_paged_roster.sql
-- Launch safety S8: an organization can have more members than one response returns
-- (PostgREST max_rows is 100), so the roster is paged: at most 100 per call, in a stable
-- order, with an offset for the next page.
drop function public.organization_roster(uuid);

create function public.organization_roster(
  p_organization_id uuid,
  p_limit integer default 100,
  p_offset integer default 0
)
returns table (user_id uuid, display_name text, role public.organization_role, share_focus_hours boolean, joined_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_org_admin(p_organization_id) then
    raise exception 'only organization admins can do this' using errcode = '42501';
  end if;
  return query
    select m.user_id, p.display_name, m.role, m.share_focus_hours, m.joined_at
    from public.organization_memberships m
    join public.profiles p on p.id = m.user_id
    where m.organization_id = p_organization_id
    order by m.role, p.display_name nulls last, m.user_id
    limit least(greatest(coalesce(p_limit, 100), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0);
end;
$$;

revoke execute on function public.organization_roster(uuid, integer, integer) from public, anon;
grant execute on function public.organization_roster(uuid, integer, integer) to authenticated;

-- ==== 20260924005800_request_guard_service_role.sql
-- Fix for 20260924005300_require_live_session: PostgREST runs the pre-request check for
-- every role it switches to, including service_role (edge functions and cron jobs), which
-- had no access to the request_guard schema, so every service-role API call failed with
-- 403 "permission denied for schema request_guard". The check itself skips service_role.
grant usage on schema request_guard to service_role;
grant execute on function request_guard.require_live_session() to service_role;

